import * as HexaUI from '.';

describe('hexa-ui', () => {
  it('should have exports', () => {
    expect(typeof HexaUI).toEqual('object');
  });

  it('should not have undefined exports', () => {
    const HexaUIImports = Object.keys(HexaUI);
    (HexaUIImports as unknown as (keyof typeof HexaUI)[]).forEach((exportKey) =>
      expect(Boolean(HexaUI[exportKey])).toEqual(true)
    );
  });
});
